    /* JADX INFO: Access modifiers changed from: private */
    public void refreshPopulationDisplayFromPlayers(TextView textView, List<PlayerInfo> list) {
        if (textView == null) {
            return;
        }
        if (list != null) {
            for (PlayerInfo playerInfo : list) {
                if (playerInfo.isMe && playerInfo.level > 0) {
                    String strValueOf = String.valueOf(playerInfo.level);
                    if (strValueOf.contentEquals(textView.getText())) {
                        return;
                    }
                    textView.setText(strValueOf);
                    return;
                }
            }
        }
        if ("--".contentEquals(textView.getText())) {
            return;
        }
        textView.setText("--");
    }

